#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <omp.h>

#if defined(__AVX512F__)
#include <immintrin.h>
#define MR 12
#define NR 32
#define MCP 4
#define NCP 4
#elif defined(__AVX2__) && defined(__FMA__)
#include <immintrin.h>
#define MR 6
#define NR 16
#define MCP 8
#define NCP 8
#else
#define MR 4
#define NR 8
#define MCP 8
#define NCP 8
#endif

#define KC 256

#if defined(__AVX512F__)

#define DECL(i) __m512 c##i##_0 = _mm512_setzero_ps(), c##i##_1 = _mm512_setzero_ps();
#define FMA(i) { __m512 av = _mm512_set1_ps(a[i]); \
    c##i##_0 = _mm512_fmadd_ps(av, b0, c##i##_0); \
    c##i##_1 = _mm512_fmadd_ps(av, b1, c##i##_1); }
#define STORE(i) { float *cr = c + (i) * ldc; \
    _mm512_storeu_ps(cr, c##i##_0); _mm512_storeu_ps(cr + 16, c##i##_1); }
#define ACCUM(i) { float *cr = c + (i) * ldc; \
    _mm512_storeu_ps(cr, _mm512_add_ps(_mm512_loadu_ps(cr), c##i##_0)); \
    _mm512_storeu_ps(cr + 16, _mm512_add_ps(_mm512_loadu_ps(cr + 16), c##i##_1)); }

static inline void kernel(int kc, const float *restrict a, const float *restrict b,
                          float *restrict c, int ldc, int accum)
{
    DECL(0) DECL(1) DECL(2) DECL(3) DECL(4) DECL(5)
    DECL(6) DECL(7) DECL(8) DECL(9) DECL(10) DECL(11)
#pragma GCC unroll 4
    for (int p = 0; p < kc; p++) {
        __m512 b0 = _mm512_load_ps(b), b1 = _mm512_load_ps(b + 16);
        FMA(0) FMA(1) FMA(2) FMA(3) FMA(4) FMA(5)
        FMA(6) FMA(7) FMA(8) FMA(9) FMA(10) FMA(11)
        a += MR; b += NR;
    }
    if (accum) {
        ACCUM(0) ACCUM(1) ACCUM(2) ACCUM(3) ACCUM(4) ACCUM(5)
        ACCUM(6) ACCUM(7) ACCUM(8) ACCUM(9) ACCUM(10) ACCUM(11)
    } else {
        STORE(0) STORE(1) STORE(2) STORE(3) STORE(4) STORE(5)
        STORE(6) STORE(7) STORE(8) STORE(9) STORE(10) STORE(11)
    }
}

#elif defined(__AVX2__) && defined(__FMA__)

#define DECL(i) __m256 c##i##_0 = _mm256_setzero_ps(), c##i##_1 = _mm256_setzero_ps();
#define FMA(i) { __m256 av = _mm256_broadcast_ss(a + (i)); \
    c##i##_0 = _mm256_fmadd_ps(av, b0, c##i##_0); \
    c##i##_1 = _mm256_fmadd_ps(av, b1, c##i##_1); }
#define STORE(i) { float *cr = c + (i) * ldc; \
    _mm256_storeu_ps(cr, c##i##_0); _mm256_storeu_ps(cr + 8, c##i##_1); }
#define ACCUM(i) { float *cr = c + (i) * ldc; \
    _mm256_storeu_ps(cr, _mm256_add_ps(_mm256_loadu_ps(cr), c##i##_0)); \
    _mm256_storeu_ps(cr + 8, _mm256_add_ps(_mm256_loadu_ps(cr + 8), c##i##_1)); }

static inline void kernel(int kc, const float *restrict a, const float *restrict b,
                          float *restrict c, int ldc, int accum)
{
    DECL(0) DECL(1) DECL(2) DECL(3) DECL(4) DECL(5)
#pragma GCC unroll 4
    for (int p = 0; p < kc; p++) {
        __m256 b0 = _mm256_load_ps(b), b1 = _mm256_load_ps(b + 8);
        FMA(0) FMA(1) FMA(2) FMA(3) FMA(4) FMA(5)
        a += MR; b += NR;
    }
    if (accum) {
        ACCUM(0) ACCUM(1) ACCUM(2) ACCUM(3) ACCUM(4) ACCUM(5)
    } else {
        STORE(0) STORE(1) STORE(2) STORE(3) STORE(4) STORE(5)
    }
}

#else

static inline void kernel(int kc, const float *restrict a, const float *restrict b,
                          float *restrict c, int ldc, int accum)
{
    float acc[MR][NR];
    memset(acc, 0, sizeof acc);
    for (int p = 0; p < kc; p++) {
        for (int i = 0; i < MR; i++) {
            float av = a[i];
            for (int j = 0; j < NR; j++)
                acc[i][j] += av * b[j];
        }
        a += MR; b += NR;
    }
    for (int i = 0; i < MR; i++)
        for (int j = 0; j < NR; j++)
            c[i * ldc + j] = accum ? c[i * ldc + j] + acc[i][j] : acc[i][j];
}

#endif

static float *g_Ap = NULL, *g_Bp = NULL;
static size_t g_Acap = 0, g_Bcap = 0;
static int g_nt = 0;

static float *grow(float *p, size_t *cap, size_t need)
{
    if (need <= *cap) return p;
    free(p);
    size_t bytes = (need * sizeof(float) + 63) & ~(size_t)63;
    p = (float *)aligned_alloc(64, bytes);
    *cap = need;
    return p;
}

static int cgroup_cpus(void)
{
    FILE *f = fopen("/sys/fs/cgroup/cpu.max", "r");
    if (f) {
        char q[64]; long period = 0;
        int r = fscanf(f, "%63s %ld", q, &period);
        fclose(f);
        if (r == 2 && strcmp(q, "max") != 0 && period > 0) {
            long quota = atol(q);
            if (quota > 0) return (int)((quota + period - 1) / period);
        }
        return 0;
    }
    f = fopen("/sys/fs/cgroup/cpu/cpu.cfs_quota_us", "r");
    if (f) {
        long quota = -1, period = 0;
        if (fscanf(f, "%ld", &quota) != 1) quota = -1;
        fclose(f);
        f = fopen("/sys/fs/cgroup/cpu/cpu.cfs_period_us", "r");
        if (f) {
            if (fscanf(f, "%ld", &period) != 1) period = 0;
            fclose(f);
        }
        if (quota > 0 && period > 0) return (int)((quota + period - 1) / period);
    }
    return 0;
}

static int num_threads(void)
{
    if (g_nt) return g_nt;
    int nt = omp_get_max_threads();
    int q = cgroup_cpus();
    if (q > 0 && q < nt) nt = q;
    if (nt < 1) nt = 1;
    g_nt = nt;
    return nt;
}

static void naive(const float *A, const float *B, float *C, int n)
{
    for (int i = 0; i < n; i++) {
        float *c = C + (size_t)i * n;
        for (int j = 0; j < n; j++) c[j] = 0.0f;
        for (int k = 0; k < n; k++) {
            float a = A[(size_t)i * n + k];
            const float *b = B + (size_t)k * n;
            for (int j = 0; j < n; j++) c[j] += a * b[j];
        }
    }
}

void matmul(const float *A, const float *B, float *C, int n)
{
    if (n <= 0) return;
    if (n < 64) { naive(A, B, C, n); return; }

    const int nip = (n + MR - 1) / MR;
    const int njp = (n + NR - 1) / NR;
    const int nkb = (n + KC - 1) / KC;
    const int nmb = (nip + MCP - 1) / MCP;
    const int nnb = (njp + NCP - 1) / NCP;

    g_Ap = grow(g_Ap, &g_Acap, (size_t)nkb * nip * KC * MR);
    g_Bp = grow(g_Bp, &g_Bcap, (size_t)nkb * njp * KC * NR);
    float *Ap = g_Ap, *Bp = g_Bp;
    int nt = num_threads();

#pragma omp parallel num_threads(nt)
    {
#pragma omp for schedule(dynamic, 4) nowait
        for (int t = 0; t < nkb * nip; t++) {
            int kb = t / nip, ip = t % nip;
            int k0 = kb * KC, kc = n - k0 < KC ? n - k0 : KC;
            int i0 = ip * MR, mr = n - i0 < MR ? n - i0 : MR;
            float *dst = Ap + (size_t)t * KC * MR;
            for (int r = 0; r < MR; r++) {
                if (r < mr) {
                    const float *src = A + (size_t)(i0 + r) * n + k0;
                    for (int p = 0; p < kc; p++) dst[p * MR + r] = src[p];
                } else {
                    for (int p = 0; p < kc; p++) dst[p * MR + r] = 0.0f;
                }
            }
        }

#pragma omp for schedule(dynamic, 4) nowait
        for (int t = 0; t < nkb * njp; t++) {
            int kb = t / njp, jp = t % njp;
            int k0 = kb * KC, kc = n - k0 < KC ? n - k0 : KC;
            int j0 = jp * NR, nr = n - j0 < NR ? n - j0 : NR;
            float *dst = Bp + (size_t)t * KC * NR;
            for (int p = 0; p < kc; p++) {
                const float *src = B + (size_t)(k0 + p) * n + j0;
                float *d = dst + p * NR;
                if (nr == NR) {
                    memcpy(d, src, NR * sizeof(float));
                } else {
                    int c = 0;
                    for (; c < nr; c++) d[c] = src[c];
                    for (; c < NR; c++) d[c] = 0.0f;
                }
            }
        }

#pragma omp barrier

#pragma omp for schedule(dynamic, 1) collapse(2)
        for (int mb = 0; mb < nmb; mb++) {
            for (int nb = 0; nb < nnb; nb++) {
                int ip0 = mb * MCP, ip1 = ip0 + MCP < nip ? ip0 + MCP : nip;
                int jp0 = nb * NCP, jp1 = jp0 + NCP < njp ? jp0 + NCP : njp;
                float tmp[MR * NR] __attribute__((aligned(64)));
                for (int kb = 0; kb < nkb; kb++) {
                    int k0 = kb * KC, kc = n - k0 < KC ? n - k0 : KC;
                    int accum = kb > 0;
                    for (int jp = jp0; jp < jp1; jp++) {
                        const float *bp = Bp + ((size_t)kb * njp + jp) * KC * NR;
                        int j0 = jp * NR, nr = n - j0 < NR ? n - j0 : NR;
                        for (int ip = ip0; ip < ip1; ip++) {
                            const float *ap = Ap + ((size_t)kb * nip + ip) * KC * MR;
                            int i0 = ip * MR, mr = n - i0 < MR ? n - i0 : MR;
                            float *c = C + (size_t)i0 * n + j0;
                            if (mr == MR && nr == NR) {
                                kernel(kc, ap, bp, c, n, accum);
                            } else {
                                kernel(kc, ap, bp, tmp, NR, 0);
                                for (int r = 0; r < mr; r++) {
                                    float *cr = c + (size_t)r * n;
                                    const float *tr = tmp + r * NR;
                                    if (accum)
                                        for (int q = 0; q < nr; q++) cr[q] += tr[q];
                                    else
                                        for (int q = 0; q < nr; q++) cr[q] = tr[q];
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}
